.map-visual svg{height:125px}.bottom-left{bottom:50px}}
.systems-button{border:1px solid #e8c99466;background:#1a302fbb;border-radius:20px;padding:9px 13px;color:#f0d7a8;font:9px 'DM Mono',monospace;letter-spacing:.12em;cursor:pointer}.systems-button span{color:#fff;margin-left:5px}.city-panel{position:absolute;z-index:8;top:50%;left:50%;width:min(440px,calc(100vw - 28px));max-height:min(680px,calc(100vh - 40px));overflow:auto;padding:20px;border-radius:15px;transform:translate(-50%,-46%) scale(.97);opacity:0;visibility:hidden;transition:.2s ease}.city-panel.open{transform:translate(-50%,-50%) scale(1);opacity:1;visibility:visible}.panel-heading{display:flex;justify-content:space-between;align-items:flex-start}.panel-heading small{font:9px 'DM Mono',monospace;letter-spacing:.14em;color:#d4bd91}.panel-heading h2{margin:5px 0 0;font-size:26px;letter-spacing:-.04em}.panel-heading>button{width:32px;height:32px;background:#ffffff0c;border:1px solid #ffffff25;border-radius:50%;font-size:22px;cursor:pointer}.panel-tabs{display:flex;gap:4px;margin:18px 0 14px;border-bottom:1px solid #ffffff20}.panel-tabs button{flex:1;padding:10px 4px;border:0;border-bottom:2px solid transparent;background:none;color:#b8c2bb;font:9px 'DM Mono',monospace;letter-spacing:.1em;cursor:pointer}.panel-tabs button.selected{border-color:#e4c48d;color:#f1d8aa}.panel-content{min-height:180px}.system-card{padding:15px;margin:10px 0;background:#ffffff0a;border:1px solid #ffffff19;border-radius:10px}.system-card h3{margin:0 0 5px;font-size:17px}.system-card p{margin:6px 0;color:#d0d5ce;font-size:12px;line-height:1.55}.system-kicker{font:9px 'DM Mono',monospace;letter-spacing:.1em;color:#a9c5ad}.stats-row{display:flex;justify-content:space-between;gap:8px;margin:12px 0}.stats-row span{font-size:10px;color:#c5cec7}.stats-row b{display:block;color:#f3d9aa;font:14px 'DM Mono',monospace;margin-top:3px}.panel-action{width:100%;margin-top:8px;padding:11px 13px;border:1px solid #dfc28c66;border-radius:7px;background:#ae895042;color:#f3dbb3;text-align:left;font-size:11px;cursor:pointer}.panel-action:hover{background:#b89a5c55}.panel-action:disabled{opacity:.42;cursor:not-allowed}.panel-footer{display:flex;justify-content:space-between;padding-top:12px;border-top:1px solid #ffffff1c;color:#dbd1bd;font:9px 'DM Mono',monospace;letter-spacing:.06em}.interior-tag{position:absolute;z-index:4;top:90px;left:50%;transform:translateX(-50%);padding:9px 14px;border-radius:20px;background:#192a28d9;border:1px solid #e3c99166;font:9px 'DM Mono',monospace;letter-spacing:.12em;display:none}.inside .interior-tag{display:block}.inside .map-card,.inside .mission-card{display:none}
